// A first output named Result is the return value; the others are `out` parameters, in 1.x order.
/// @name DreamShaderTests/Migrate/MF_MgResult
/// @desc Returns the colour and its weight.
/// @library DreamShader|Tests
export float3 MF_MgResult(float3 InColor, out float Weight)
{
    float3 Result = float3(0, 0, 0);
    Result = InColor * 0.5;
    Weight = dot(InColor, float3(0.299, 0.587, 0.114));

    return Result;
}
